"""Sales pipeline expected-value forecaster.

Deals are dicts: {"amount_cents": int, "stage": str, "close_month": "YYYY-MM"}.
All math is exact integer-cent * Decimal-probability; results are Decimal cents.
"""

from decimal import ROUND_HALF_EVEN, Decimal

STAGE_PROBABILITIES = {
    "lead": Decimal("0.05"),
    "qualified": Decimal("0.20"),
    "demo": Decimal("0.40"),
    "proposal": Decimal("0.65"),
    "verbal": Decimal("0.90"),
}

_CENT = Decimal("0.01")


def _prob(stage):
    try:
        return STAGE_PROBABILITIES[stage]
    except (KeyError, TypeError):
        valid = ", ".join(sorted(STAGE_PROBABILITIES))
        raise ValueError(f"unknown stage {stage!r}; valid stages: {valid}") from None


def ev_by_month(deals):
    """Expected value in cents grouped by expected close month."""
    monthly = {}
    for deal in deals:
        ev = (Decimal(deal["amount_cents"]) * _prob(deal["stage"])).quantize(
            _CENT, rounding=ROUND_HALF_EVEN
        )
        monthly[deal["close_month"]] = monthly.get(deal["close_month"], _CENT * 0) + ev
    return monthly


def totals(deals):
    """Weighted (probability-adjusted) and unweighted (full-amount) pipeline EV."""
    weighted = sum(ev_by_month(deals).values(), _CENT * 0)
    unweighted = sum((Decimal(d["amount_cents"]) for d in deals), _CENT * 0)
    return {"weighted": weighted, "unweighted": unweighted}

